<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
if (!dogoflow_cart_enabled()) { redirect('/products.php'); }
Auth::requireLogin();

if (Auth::role() !== 'customer') {
    redirect(Auth::dashboardPath());
}

$customerId = (int) Auth::userId();
$cartStmt = db()->prepare('SELECT id FROM carts WHERE customer_id = ? LIMIT 1');
$cartStmt->execute([$customerId]);
$cartId = (int) ($cartStmt->fetchColumn() ?: 0);

if (!$cartId) {
    $items = [];
} else {
    $stmt = db()->prepare(
        "SELECT ci.id AS cart_item_id, ci.quantity, p.id, p.name, p.slug, p.price, p.stock, p.image,
                sp.business_name, sp.store_slug
         FROM cart_items ci
         INNER JOIN products p ON p.id = ci.product_id
         INNER JOIN users u ON u.id = p.seller_id AND u.role = 'seller' AND u.status = 'active'
         INNER JOIN seller_profiles sp ON sp.user_id = p.seller_id
             AND sp.status = 'active' AND sp.approval_status = 'approved'
         WHERE ci.cart_id = ? AND p.status = 'active'
         ORDER BY ci.created_at DESC"
    );
    $stmt->execute([$cartId]);
    $items = $stmt->fetchAll();
}

$subtotal = 0.0;
foreach ($items as &$item) {
    $item['quantity'] = min((int) $item['quantity'], (int) $item['stock']);
    $item['line_total'] = (float) $item['price'] * $item['quantity'];
    $subtotal += $item['line_total'];
}
unset($item);

$pageTitle = 'Shopping Cart · DogoFlow';
?>

