n="<?=e(url('/cart/update.php'))?>" class="df-qty"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="cart_item_id" value="<?= (int)$item['cart_item_id']?>"><button type="submit" name="quantity" value="<?=max(1,(int)$item['quantity']-1)?>" aria-label="Decrease quantity">−</button><input name="display_quantity" value="<?= (int)$item['quantity']?>" readonly aria-label="Quantity"><button type="submit" name="quantity" value="<?=min((int)$item['stock'],(int)$item['quantity']+1)?>" aria-label="Increase quantity">+</button></form><strong>GH₵ <?=number_format((float)$item['line_total'],2)?></strong><br><a class="df-danger" href="<?=e(url('/cart/remove.php?id='.(int)$item['cart_item_id'].'&csrf='.rawurlencode(csrf_token())))?>" style="font-size:.76rem;font-weight:850;text-decoration:none">Remove</a></div></div><?php endforeach; ?></section><aside class="df-card df-summary"><span class="df-eyebrow">ORDER SUMMARY</span><h2 style="margin:5px 0 15px">Ready to checkout?</h2><div class="df-summary-row"><span>Items</span><strong><?=count($items)?></strong></div><div class="df-total"><span>Total</span><strong>GH₵ <?=number_format($subtotal,2)?></strong></div><p class="df-sub" style="font-size:.8rem;margin:12px 0 18px">Delivery fees and payment charges, if applicable, are shown during checkout.</p><a class="df-btn df-primary df-full" href="<?=e(url('/checkout.php'))?>">Proceed to checkout →</a></aside></div><?php endif; ?></main></body></html>